# Проверка на хостинге: схема v6 и чтение документов под Node хостинга
grep -a "кира" ~/log/devalby.ru.error.log | grep -a "схема" | tail -2 | cut -c1-100
NODE=/usr/nvm/versions/node/v21.5.0/bin/node; ls -la $NODE | cut -c1-80
mkdir -p /tmp/kira-fx && cd /tmp/kira-fx
echo '' | base64 -d > akt.pdf
echo '' | base64 -d > dogovor.docx
echo '' | base64 -d > smeta.xlsx
cat > t.mjs <<"JS"
const { extractText } = await import(process.env.HOME + "/devalby.ru/www/src/docs/extract.js");
const fs = await import("node:fs");
for (const f of ["akt.pdf", "dogovor.docx", "smeta.xlsx"]) { const r = await extractText(fs.readFileSync(f), { name: f }); console.log(process.version, f, r.status, r.pages || "", JSON.stringify((r.text || "").slice(0, 60)), r.note || ""); }
JS
"$NODE" t.mjs 2>&1 | grep -v Warning
cd ~; rm -rf /tmp/kira-fx
du -sh ~/devalby.ru/www/node_modules
